// sverka.config.ts — verification pipeline for @sverka/storage.
// Defines the `verify` pipeline (format → lint → typecheck → test → build)
// and executes it on the local host engine when run via `bun run verify`.

import { join } from "node:path";
import process from "node:process";
import {
  Entry,
  Pipeline,
  ShellStep,
  computeGraphId,
  computeRunPlanId,
  manual,
  synthesize,
} from "@sverka/workflow";
import type { RunPlan } from "@sverka/workflow";
import {
  createAllowlist,
  createEngine,
  createHostDriver,
} from "@sverka/runtime";

const pipeline = new Pipeline("verify", { name: "Verify" });

// Cheap, mechanical checks first; the build runs last once everything else
// is known-good. Each step depends on the previous so failures stop the run.
new ShellStep(pipeline, "format", {
  command: "bun run format",
  timeout: 120_000,
});
new ShellStep(pipeline, "lint", {
  command: "bun run lint",
  dependsOn: ["format"],
  timeout: 120_000,
});
new ShellStep(pipeline, "typecheck", {
  command: "bun run typecheck",
  dependsOn: ["lint"],
  timeout: 180_000,
});
new ShellStep(pipeline, "test", {
  command: "bun run test",
  dependsOn: ["typecheck"],
  timeout: 300_000,
});
new ShellStep(pipeline, "build", {
  command: "bun run build",
  dependsOn: ["test"],
  timeout: 300_000,
});

new Entry(pipeline, "local", { trigger: manual(), roots: ["format"] });

export default pipeline;

/** Synthesize the pipeline and bind it into an executable RunPlan. */
export function buildRunPlan(): RunPlan {
  const graph = synthesize(pipeline);
  const def = graph.project.pipelines[0];
  if (!def) throw new Error("synthesized graph contains no pipelines");
  const entry = def.entries[0];
  if (!entry) throw new Error("verify pipeline has no entry point");
  const base = {
    apiVersion: "sverka.dev/v1run" as const,
    graphId: computeGraphId(graph),
    entry: { id: entry.id, trigger: entry.trigger },
    inputs: {},
    steps: def.steps,
  };
  return {
    ...base,
    id: computeRunPlanId(base),
    createdAt: new Date().toISOString(),
  };
}

// Environment variables forwarded from the host into step processes.
const ENV_ALLOWLIST = [
  "HOME",
  "USER",
  "LANG",
  "TERM",
  "TMPDIR",
  "XDG_CACHE_HOME",
  "CI",
  "NODE_ENV",
  "NO_COLOR",
  "FORCE_COLOR",
];

async function main(): Promise<void> {
  const workspace = process.cwd();
  const plan = buildRunPlan();
  const engine = createEngine({
    drivers: [
      createHostDriver({
        enabled: true,
        allowlist: createAllowlist(["bun"]),
        envAllowlist: ENV_ALLOWLIST,
      }),
    ],
  });

  let status = "failure";
  for await (const event of engine.run({
    plan,
    workspace,
    artifactDir: join(workspace, ".sverka", "artifacts"),
  })) {
    switch (event.type) {
      case "step-started":
        console.log(`--- ${event.stepId}`);
        break;
      case "step-succeeded":
        console.log(`ok   ${event.stepId} (${event.durationMs}ms)`);
        break;
      case "step-failed":
        console.log(`FAIL ${event.stepId}: ${event.error}`);
        if (event.stdout) console.log(event.stdout.trimEnd());
        if (event.stderr) console.log(event.stderr.trimEnd());
        break;
      case "step-skipped":
        console.log(`skip ${event.stepId}`);
        break;
      case "diagnostic":
        if (event.severity !== "info")
          console.log(`${event.severity}: ${event.message}`);
        break;
      case "run-completed":
        status = event.status;
        console.log(`verify ${event.status} (${event.durationMs}ms)`);
        break;
    }
  }
  process.exitCode = status === "success" ? 0 : 1;
}

if (import.meta.main) {
  await main();
}

